package com.yeyamo_mobile.api.feed_service.domain.model;
import java.time.Instant;import java.util.*;
public record FeedPost(UUID postId,String authorId,String caption,String visibility,String status,UUID catalogAssetId,String referenceType,String referenceId,List<UUID>mediaIds,List<String>hashtags,String countryCode,String cityId,String languageCode,Double latitude,Double longitude,Instant publishedAt,Instant updatedAt){
 public FeedPost{if(postId==null)throw new IllegalArgumentException("postId is required");if(authorId==null||authorId.isBlank())throw new IllegalArgumentException("authorId is required");if((latitude==null)!=(longitude==null))throw new IllegalArgumentException("coordinates must be supplied together");referenceType=referenceType==null?"NONE":referenceType;countryCode=countryCode==null?null:countryCode.trim().toUpperCase(Locale.ROOT);cityId=cityId==null?null:cityId.trim();languageCode=languageCode==null?null:languageCode.trim();mediaIds=mediaIds==null?List.of():List.copyOf(mediaIds);hashtags=hashtags==null?List.of():List.copyOf(hashtags);}
 public FeedPost(UUID postId,String authorId,String caption,String visibility,String status,UUID catalogAssetId,String referenceType,String referenceId,List<UUID>mediaIds,List<String>hashtags,String countryCode,String languageCode,Instant publishedAt,Instant updatedAt){this(postId,authorId,caption,visibility,status,catalogAssetId,referenceType,referenceId,mediaIds,hashtags,countryCode,null,languageCode,null,null,publishedAt,updatedAt);}
 public FeedPost(UUID postId,String authorId,String caption,String visibility,String status,UUID catalogAssetId,List<UUID>mediaIds,List<String>hashtags,Instant publishedAt,Instant updatedAt){this(postId,authorId,caption,visibility,status,catalogAssetId,catalogAssetId==null?"NONE":"PLACE",catalogAssetId==null?null:catalogAssetId.toString(),mediaIds,hashtags,null,null,null,null,null,publishedAt,updatedAt);}
 public boolean available(){return "PUBLISHED".equals(status)&&"PUBLIC".equals(visibility)&&publishedAt!=null;}
}
